#!/bin/sh
# Generated by forge. PostToolUse(Edit|Write): formats the edited file silently,
# lints it and runs the ast-grep forbid rules on it. Findings on lines added
# during this turn (or since HEAD, before the first prompt) go back to Claude as
# additionalContext (<= 20 lines). Nothing on success.
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
file=$(json_get file_path)
[ -n "$file" ] || exit 0
file=$(rel_path "$file") || exit 0
[ -f "$file" ] || exit 0
case $file in .forge/*|.claude/*|.git/*|node_modules/*|.venv/*) exit 0 ;; esac
IFS='
'
FORGE_TMP=$(mktemp -d "${TMPDIR:-/tmp}/forge-edit.XXXXXX") || exit 0
trap 'rm -rf "$FORGE_TMP"' EXIT HUP INT TERM

@@CHECKS@@

FORGE_FORBID='@@FORBID@@'

forge_file_stage format "$file" > /dev/null 2>&1
# the lines added to this file during the turn (base: the turn snapshot, else HEAD)
mode=--changed
FORGE_SNAP=''
FORGE_BASE_REV=$(git rev-parse -q --verify HEAD 2>/dev/null)
snap=$(turn_dir)
if [ -f "$snap/head" ]; then FORGE_SNAP=$snap; FORGE_BASE_REV=$(cat "$snap/head"); fi
printf '%s\n' "$file" > "$FORGE_TMP/changed"
base_file "$file" "$FORGE_TMP/base"
added_lines "$file" "$FORGE_TMP/base" > "$FORGE_TMP/added"
forge_file_stage lint "$file" > "$FORGE_TMP/report" 2>&1
if [ -n "$FORGE_FORBID" ] && [ -f .forge/ast-grep/sgconfig.yml ]; then
  astgrep scan -c .forge/ast-grep/sgconfig.yml --filter "^($FORGE_FORBID)\$" --json=stream "$file" > "$FORGE_TMP/forbid" 2>/dev/null
  forge_sg_report "$FORGE_TMP/forbid" >> "$FORGE_TMP/report"
fi
[ -s "$FORGE_TMP/report" ] || exit 0
ctx=$(first_lines 20 < "$FORGE_TMP/report" | json_escape)
printf '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"%s"}}\n' "$ctx"
exit 0
